export const CLOCK='2026-10-08T23:00:00.000Z';
export const STATUSES=['Submitted','Assigned','In progress','Awaiting confirmation','Closed'];
export const UNITS=['Riverbend','Northbank','Lakeside'];
export const CATEGORIES=['Device','Access','Application','Network'];
export const TECHNICIANS=['Alex T.','Morgan T.','Sam T.'];
const priorities={P1:4,P2:24,P3:72};
function check(condition,message){if(!condition)throw new Error(message)}
function requiredText(value,min,max,label){check(typeof value==='string',`${label} is required.`);const t=value.trim();check(t.length>=min&&t.length<=max,`${label} must contain ${min}–${max} characters.`);return t}
export function priority(impact,urgency){check(['High','Standard'].includes(impact)&&['High','Standard'].includes(urgency),'Choose a valid impact and urgency.');return impact==='High'&&urgency==='High'?'P1':impact==='High'||urgency==='High'?'P2':'P3'}
function event(now,role,action,status,note=''){return {at:now,role,action,status,note}}
export function createRequest(state,input,role){check(['Requester','Coordinator'].includes(role),'Only a requester or coordinator can submit a request.');const title=requiredText(input.title,5,120,'Title'),description=requiredText(input.description,10,1000,'Description');check(UNITS.includes(input.unit),'Choose a valid unit.');check(CATEGORIES.includes(input.category),'Choose a valid category.');const p=priority(input.impact,input.urgency);const id='RF-'+(Math.max(1000,...state.records.map(x=>Number(x.id.slice(3))))+1);const record={id,title,description,unit:input.unit,category:input.category,impact:input.impact,urgency:input.urgency,priority:p,status:'Submitted',owner:'Unassigned',createdAt:state.now,dueAt:new Date(Date.parse(state.now)+priorities[p]*3600000).toISOString(),resolution:'',closedAt:null,events:[event(state.now,role,'Request submitted','Submitted',role==='Coordinator'?'Assisted intake':'Self-service intake')]};state.records.unshift(record);return record}
export function act(state,id,action,role,input={}){const r=state.records.find(x=>x.id===id);check(r,'Request not found.');let next,note='',label;
if(action==='assign'){check(role==='Coordinator','Only a coordinator can assign a request.');check(r.status==='Submitted','Only Submitted requests can be assigned.');check(TECHNICIANS.includes(input.owner),'Select a technician.');next='Assigned';note=input.owner;label='Technician assigned';}
else if(action==='start'){check(role==='Technician','Only a technician can start work.');check(r.status==='Assigned','Only Assigned requests can start work.');next='In progress';label='Work started';}
else if(action==='resolve'){check(role==='Technician','Only a technician can propose a resolution.');check(r.status==='In progress','Only In progress requests can be resolved.');note=requiredText(input.note,10,1000,'Resolution');next='Awaiting confirmation';label='Resolution proposed';}
else if(action==='confirm'){check(role==='Requester','Only a requester can confirm a resolution.');check(r.status==='Awaiting confirmation','Only requests awaiting confirmation can close.');next='Closed';label='Requester confirmed service restored';}
else if(action==='reject'){check(role==='Requester','Only a requester can reject a resolution.');check(r.status==='Awaiting confirmation','Only requests awaiting confirmation can be rejected.');note=requiredText(input.note,10,1000,'Rejection reason');next='In progress';label='Requester rejected resolution';}
else throw new Error('Unsupported action.');
if(action==='assign')r.owner=input.owner;if(action==='resolve')r.resolution=note;r.status=next;r.closedAt=next==='Closed'?state.now:null;r.events.push(event(state.now,role,label,next,note));return r}
export function stats(state){return {open:state.records.filter(r=>r.status!=='Closed').length,overdue:state.records.filter(r=>r.status!=='Closed'&&Date.parse(r.dueAt)<Date.parse(state.now)).length,awaiting:state.records.filter(r=>r.status==='Awaiting confirmation').length,closed:state.records.filter(r=>r.status==='Closed').length}}
export function filterRecords(state,query='',status='All'){const q=query.trim().toLowerCase();return state.records.filter(r=>(status==='All'||r.status===status)&&[r.id,r.title,r.unit,r.owner].some(x=>x.toLowerCase().includes(q)))}
export function csvCell(value){let s=String(value??'');if(/^[=+\-@\t\r]/.test(s.trimStart())||/^[\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}
export function toCSV(records){const fields=['id','title','unit','category','priority','status','owner','createdAt','dueAt','resolution','closedAt'];return fields.join(',')+'\r\n'+records.map(r=>fields.map(f=>csvCell(r[f])).join(',')).join('\r\n')}
export function advanceClock(state,hours){check(Number.isFinite(hours)&&hours>0&&hours<=168,'Advance by 1–168 hours.');state.now=new Date(Date.parse(state.now)+hours*3600000).toISOString();return state.now}
export function seed(){const state={schema:1,now:CLOCK,records:[]};const rows=[
 ['Shared printer unavailable','Riverbend','Device','High','Standard',26,'Submitted',null],
 ['Counter workstations offline','Northbank','Network','High','High',2,'Assigned','Alex T.'],
 ['Scanner connection intermittent','Lakeside','Device','Standard','Standard',24,'In progress','Morgan T.'],
 ['Training application access restored','Riverbend','Access','Standard','High',6,'Awaiting confirmation','Sam T.'],
 ['Spare monitor installed','Northbank','Device','Standard','Standard',60,'Closed','Alex T.'],
 ['Team dashboard will not load','Riverbend','Application','High','Standard',30,'In progress','Morgan T.'],
 ['Desk headset replaced','Lakeside','Device','Standard','Standard',48,'Closed','Sam T.'],
 ['Meeting room screen flickers','Riverbend','Device','Standard','Standard',1,'Submitted',null]
 ];rows.forEach(([title,unit,category,impact,urgency,age,status,owner],i)=>{state.now=new Date(Date.parse(CLOCK)-age*3600000).toISOString();const r=createRequest(state,{title,unit,category,impact,urgency,description:'Synthetic demonstration fault. Staff require support to restore normal service.'},'Requester');if(status!=='Submitted')act(state,r.id,'assign','Coordinator',{owner});if(['In progress','Awaiting confirmation','Closed'].includes(status))act(state,r.id,'start','Technician');if(['Awaiting confirmation','Closed'].includes(status))act(state,r.id,'resolve','Technician',{note:'Service restored using a tested configuration. Requester verification is required.'});if(status==='Closed'){state.now=new Date(Date.parse(CLOCK)-(i===4?2:6)*3600000).toISOString();act(state,r.id,'confirm','Requester')}});state.now=CLOCK;return state}
export function validState(s){return !!s&&s.schema===1&&Number.isFinite(Date.parse(s.now))&&Array.isArray(s.records)&&s.records.length<=10000&&s.records.every(r=>r&&/^RF-\d+$/.test(r.id)&&['title','description','unit','category','owner','resolution'].every(k=>typeof r[k]==='string')&&STATUSES.includes(r.status)&&['P1','P2','P3'].includes(r.priority)&&Number.isFinite(Date.parse(r.dueAt))&&Array.isArray(r.events)&&r.events.every(e=>e&&['at','role','action','status','note'].every(k=>typeof e[k]==='string')))&&new Set(s.records.map(r=>r.id)).size===s.records.length}
